INSERT INTO problems (id, slug, title, difficulty, category, description_markdown, time_limit_ms, memory_limit_kb)
VALUES ('8d5e97ac-a2c4-5226-861a-235359a5c1a0', 'meeting-rooms-ii', 'Meeting Rooms II', 'Medium', 'Intervals', 'Given an array of meeting time intervals consisting of start and end times [[s1,e1],[s2,e2],...] (si < ei), find the minimum number of conference rooms required.

